import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderDiscountTest {

    private static final Instant NOW = Instant.parse("2026-10-01T10:00:00Z");

    @Test
    void halfAPercentOfOneZlotyIsOneGrosz() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(100), NOW);

            orders.applyDiscount(id, "0.5");

            assertEquals(Money.pln(99), orders.summary(id).total());
        }
    }

    @Test
    void discountIsRoundedHalfUpToAMinorUnit() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), NOW);

            orders.applyDiscount(id, "12.5");

            // 12.5% of 1000 = 125 exactly
            assertEquals(Money.pln(875), orders.summary(id).total());
        }
    }

    @Test
    void discountOfExactlyHalfMinorUnitRoundsUp() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(333), NOW);

            // 15% of 333 = 49.95 minor units -> 50
            orders.applyDiscount(id, "15");

            assertEquals(Money.pln(283), orders.summary(id).total());
        }
    }

    @Test
    void rejectsPercentOutsideZeroToHundredAndNonNumericInput() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), NOW);

            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, "-1"));
            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, "100.01"));
            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, "abc"));
            assertThrows(IllegalArgumentException.class, () -> orders.applyDiscount(id, null));

            assertEquals(Money.pln(1000), orders.summary(id).total());
        }
    }
}
}
